import java.io.*;
import java.util.*;

class Scan {
    private Deque<String> buffer = new ArrayDeque<>();
    private BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

    public <T> T next(Class<T> clazz) {
        while (true) {
            if (!buffer.isEmpty()) {
                String token = buffer.pollFirst();
                if (clazz == Integer.class) {
                    return clazz.cast(Integer.parseInt(token));
                } else if (clazz == Long.class) {
                    return clazz.cast(Long.parseLong(token));
                } else if (clazz == String.class) {
                    return clazz.cast(token);
                } else {
                    throw new RuntimeException("Unsupported type");
                }
            }
            String line;
            try {
                line = reader.readLine();
                if (line == null) throw new RuntimeException("Fail to read");
            } catch (IOException e) {
                throw new RuntimeException("Fail to read", e);
            }
            String[] parts = line.trim().split("\\s+");
            buffer.clear();
            for (String p : parts) {
                if (!p.isEmpty()) buffer.addLast(p);
            }
        }
    }
}

public class Main {
    static boolean is_prime(int x) {
        for (int i = 2; i <= (int) Math.sqrt(x); i++) {
            if (x % i == 0) {
                return false;
            }
        }
        return true;
    }

    static int next_prime(int x) {
        int aux = x + 1;
        while (!is_prime(aux)) {
            aux += 1;
        }
        return aux;
    }

    static void _main() {
        Scan scan = new Scan();
        int n = scan.next(Integer.class);
        int m = scan.next(Integer.class);
        boolean result = next_prime(n) == m;
        System.out.println(result ? "YES" : "NO");
    }

    public static void main(String[] args) {
        _main();
    }
}

